import { siteContentPath, SITES_PATH_PREFIX } from "@imsweb/contracts/paths";
import type { Context } from "hono";
import { html as renderHtml } from "hono/html";
import type { AppEnvironment } from "@/app";
import type { SitePackageRevisionRecord } from "@/ports/repositories";
import type {
    PreviewSitePackageParams,
    PublicSitePackageParams,
    PublishedSitePackageParams,
} from "@/domains/delivery/site-packages/request";
import type {
    PreviewSitePackageContentResponseBoundary,
    PublicSitePackageResponse,
    PublishedSitePackageContentResponseBoundary,
    SitePackageErrorResponse,
    SitePackageNotFoundResponseBoundary,
    SitePackageShellResponseBoundary,
} from "@/domains/delivery/site-packages/response";
import {
    mainSiteOrigin,
    manifestEntries,
    requestedPackageAssetPath,
    sitePackageContentCsp,
    sitePackageFrameAncestorOrigins,
    sitePackageManifest,
} from "@/domains/delivery/site-packages/site-package-support";
import { sitePackageRepository, services } from "@/middleware/hono-context";
import type { ValidatedRequestContext } from "@/middleware/request-validation";
import { optimizeSitePackageContent } from "@/domains/delivery/site-packages/site-package-content";
import type { ObjectStorage } from "@/ports/object-storage";
import { objectReadResponse } from "@/utils/http/object-read-response";
import { storedObjectResponse } from "@/utils/http/stored-object-response";
import { sha256Hex } from "@/utils/crypto/sha256";

const DIRECT_ASSET_EXTENSION =
    /\.(?:avif|bmp|gif|ico|jpe?g|jfif|otf|png|ttf|webp|woff2?)$/i;
// The iframe deliberately omits `allow-same-origin`, so its fetch origin is
// the literal opaque origin. Public package assets never accept credentials.
const SITE_PACKAGE_SANDBOX_ORIGIN = "null";

function notFound(c: Context<AppEnvironment>): Response {
    return c.text(
        "Not Found",
        404,
    ) satisfies SitePackageNotFoundResponseBoundary;
}

function publicPackageRevision(
    sitePackage: {
        id: string;
        published_revision_id: string | null;
    },
    revision: SitePackageRevisionRecord | null,
): (SitePackageRevisionRecord & { published_at: number }) | null {
    return revision !== null &&
        revision.published_at !== null &&
        revision.package_id === sitePackage.id &&
        revision.id === sitePackage.published_revision_id
        ? (revision as SitePackageRevisionRecord & { published_at: number })
        : null;
}

export async function handleGetPublicSitePackage(
    c: ValidatedRequestContext<
        AppEnvironment,
        "param",
        PublicSitePackageParams
    >,
): Promise<Response> {
    const { slug } = c.req.valid("param");
    if (!slug) {
        return c.json(
            { error: "站点包不存在" } satisfies SitePackageErrorResponse,
            404,
        );
    }
    const sitePackage =
        await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage?.published_revision_id) {
        return c.json(
            { error: "站点包不存在" } satisfies SitePackageErrorResponse,
            404,
        );
    }
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(
            sitePackage.id,
            sitePackage.published_revision_id,
        ),
    );
    if (!revision) {
        return c.json(
            { error: "站点包不存在" } satisfies SitePackageErrorResponse,
            404,
        );
    }
    return c.json({
        slug: sitePackage.slug,
        title: sitePackage.title,
        description: sitePackage.description,
        revisionId: revision.id,
        revisionNumber: revision.revision_number,
        runtimeMode: revision.runtime_mode,
        publishedAt: revision.published_at,
        siteUrl: `${mainSiteOrigin(c)}${SITES_PATH_PREFIX}/${sitePackage.slug}`,
        contentUrl: `${mainSiteOrigin(c)}${siteContentPath(`/${sitePackage.slug}/${revision.id}/`)}`,
    } satisfies PublicSitePackageResponse);
}

function sitePackageShellCsp(
    contentOrigin: string,
    iconUrl: string | null,
): string {
    let iconSource = "'none'";
    if (iconUrl) {
        try {
            iconSource = new URL(iconUrl).origin;
        } catch {
            iconSource = "'none'";
        }
    }
    return [
        "default-src 'none'",
        "base-uri 'none'",
        "connect-src 'none'",
        `frame-src ${contentOrigin}`,
        "frame-ancestors 'none'",
        "form-action 'none'",
        `img-src ${iconSource}`,
        "object-src 'none'",
        "script-src 'none'",
        "style-src 'unsafe-inline'",
    ].join("; ");
}

function sitePackageShell(
    title: string,
    contentUrl: string,
    iconUrl: string | null,
): string {
    const iconLink = iconUrl
        ? renderHtml`\n  <link rel="icon" href="${iconUrl}">`
        : "";
    return String(renderHtml`<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">${iconLink}
  <title>${title} | IMSWeb</title>
  <style>
    :root { color-scheme: light dark; font-family: Geist, "Noto Sans SC", "PingFang SC", sans-serif; }
    * { box-sizing: border-box; letter-spacing: 0; }
    html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }
    body { color: CanvasText; background: Canvas; }
    .site-return {
      position: fixed;
      z-index: 1;
      bottom: max(12px, env(safe-area-inset-bottom));
      left: env(safe-area-inset-left, 0px);
      display: inline-flex;
      width: 44px;
      height: 44px;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      padding: 0;
      border: 1px solid color-mix(in srgb, CanvasText 18%, transparent);
      border-left: 0;
      border-radius: 0 8px 8px 0;
      color: CanvasText;
      background: color-mix(in srgb, Canvas 88%, transparent);
      box-shadow: 4px 0 16px color-mix(in srgb, CanvasText 16%, transparent);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      font-size: 13px;
      font-weight: 600;
      line-height: 1;
      text-decoration: none;
      transition: width 160ms ease, padding 160ms ease, background-color 120ms ease;
    }
    .site-return:hover { background: color-mix(in srgb, Canvas 96%, Highlight 4%); }
    .site-return:focus-visible { outline: 3px solid Highlight; outline-offset: 3px; }
    .site-return-icon { flex: 0 0 20px; text-align: center; font-size: 20px; font-weight: 400; line-height: 1; }
    .site-return-label {
      max-width: 0;
      margin-left: 0;
      overflow: hidden;
      opacity: 0;
      white-space: nowrap;
      transition: max-width 160ms ease, margin-left 160ms ease, opacity 120ms ease;
    }
    iframe { display: block; width: 100%; height: 100%; height: 100dvh; border: 0; background: Canvas; }
    @media (hover: hover) and (pointer: fine) {
      .site-return:hover, .site-return:focus-visible {
        width: 108px;
        justify-content: flex-start;
        padding: 0 12px 0 10px;
      }
      .site-return:hover .site-return-label,
      .site-return:focus-visible .site-return-label {
        max-width: 56px;
        margin-left: 8px;
        opacity: 1;
      }
    }
    @media (prefers-reduced-motion: reduce) {
      .site-return, .site-return-label { transition: none; }
    }
  </style>
</head>
<body>
  <nav aria-label="站点导航">
    <a class="site-return" href="/" aria-label="返回 IMSWeb 主站" title="返回 IMSWeb 主站">
      <span class="site-return-icon" aria-hidden="true">←</span>
      <span class="site-return-label">IMSWeb</span>
    </a>
  </nav>
  <iframe src="${contentUrl}" title="${title}" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe>
</body>
</html>`);
}

function safeSitePackageIconUrl(value: string | null): string | null {
    if (!value) return null;
    try {
        const url = new URL(value);
        return ["http:", "https:"].includes(url.protocol) &&
            !url.username &&
            !url.password
            ? url.href
            : null;
    } catch {
        return null;
    }
}

async function sitePackageIconUrl(
    storage: ObjectStorage | undefined,
    revision: SitePackageRevisionRecord,
    contentUrl: string,
): Promise<string | null> {
    const manifest = sitePackageManifest(revision);
    if (!manifest.iconPath) return null;
    const objectKey = manifest.entries.get(manifest.iconPath);
    if (!objectKey) {
        throw new Error("Stored site-package manifest icon path is invalid");
    }
    const encodedPath = manifest.iconPath
        .split("/")
        .map(encodeURIComponent)
        .join("/");
    const fallback = new URL(encodedPath, contentUrl).href;
    if (!storage) return fallback;
    if (storage.createPublicReadUrl) {
        try {
            const direct = safeSitePackageIconUrl(
                await storage.createPublicReadUrl(objectKey, {
                    publicPath: new URL(fallback).pathname,
                }),
            );
            if (direct) return direct;
        } catch {
            // Fall through to a signed or same-origin read URL.
        }
    }
    if (storage.createReadUrl) {
        try {
            const target = await storage.createReadUrl(objectKey, {
                method: "GET",
            });
            const direct = safeSitePackageIconUrl(target?.url ?? null);
            if (direct) return direct;
        } catch {
            // Fall through to the manifest-checked content route.
        }
    }
    return fallback;
}

export async function handleServePublishedSitePackageShell(
    c: ValidatedRequestContext<
        AppEnvironment,
        "param",
        PublicSitePackageParams
    >,
): Promise<Response> {
    const { slug } = c.req.valid("param");
    if (!slug) return notFound(c);
    const sitePackage =
        await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage?.published_revision_id) return notFound(c);
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(
            sitePackage.id,
            sitePackage.published_revision_id,
        ),
    );
    if (!revision) return notFound(c);
    const contentOrigin = mainSiteOrigin(c);
    const contentUrl = `${contentOrigin}${siteContentPath(`/${slug}/${revision.id}/`)}`;
    const iconUrl = await sitePackageIconUrl(
        services(c).storage,
        revision,
        contentUrl,
    );
    c.header("Cache-Control", "no-cache");
    c.header(
        "Content-Security-Policy",
        sitePackageShellCsp(contentOrigin, iconUrl),
    );
    c.header(
        "Permissions-Policy",
        "camera=(), geolocation=(), microphone=(), payment=(), usb=()",
    );
    c.header("Referrer-Policy", "no-referrer");
    c.header("X-Frame-Options", "DENY");
    return c.html(
        sitePackageShell(sitePackage.title, contentUrl, iconUrl),
    ) satisfies SitePackageShellResponseBoundary;
}

async function serveRevisionAsset(
    c: Context<AppEnvironment>,
    revision: SitePackageRevisionRecord,
    slug: string,
    routeSegments: readonly string[],
    preview: boolean,
): Promise<Response> {
    const runtime = services(c);
    if (!runtime.storage) throw new Error("Object storage unavailable");
    const assetPath = requestedPackageAssetPath(
        c.req.raw,
        routeSegments,
        revision.entry_path,
    );
    if (!assetPath) return notFound(c);
    const objectKey = manifestEntries(revision).get(assetPath);
    const expectedKey =
        `site-packages/${revision.package_id}/revisions/` +
        `${revision.id}/files/${assetPath}`;
    if (!objectKey || objectKey !== expectedKey) return notFound(c);
    if (!preview && DIRECT_ASSET_EXTENSION.test(assetPath)) {
        const response = await objectReadResponse(
            c.req.raw,
            runtime.storage,
            objectKey,
            {
                "Access-Control-Allow-Origin": SITE_PACKAGE_SANDBOX_ORIGIN,
                "Cache-Control": "public, max-age=31536000, immutable",
                "X-Site-Package": `${slug}:${revision.id}`,
            },
        );
        return response ?? notFound(c);
    }
    const stored = await runtime.storage.get(objectKey);
    if (!stored) return notFound(c);
    const object = await optimizeSitePackageContent(stored);
    const htmlContent = /^text\/html(?:;|$)/i.test(object.contentType);
    const siteOrigin = mainSiteOrigin(c);
    const contentSource = new URL(
        `/${routeSegments.map(encodeURIComponent).join("/")}/`,
        siteOrigin,
    ).href;
    const directTarget =
        !preview && htmlContent && runtime.storage.createReadUrl
            ? await runtime.storage.createReadUrl(objectKey)
            : null;
    let directAssetOrigin: string | undefined;
    if (directTarget) {
        try {
            directAssetOrigin = new URL(directTarget.url).origin;
        } catch {
            directAssetOrigin = undefined;
        }
    }
    const headers = new Headers({
        "Access-Control-Allow-Origin": SITE_PACKAGE_SANDBOX_ORIGIN,
        "Cache-Control": preview
            ? "private, no-store"
            : htmlContent
              ? "public, max-age=0, must-revalidate"
              : "public, max-age=31536000, immutable",
        "Content-Security-Policy": sitePackageContentCsp(
            revision.runtime_mode,
            sitePackageFrameAncestorOrigins(siteOrigin),
            contentSource,
            directAssetOrigin,
        ),
        "Permissions-Policy":
            "camera=(), geolocation=(), microphone=(), payment=(), usb=()",
        "Referrer-Policy": "no-referrer",
        "X-Site-Package": `${slug}:${revision.id}`,
    });
    headers.delete("X-Frame-Options");
    return storedObjectResponse(c.req.raw, object, headers);
}

export async function handleServePublishedSitePackage(
    c: ValidatedRequestContext<
        AppEnvironment,
        "param",
        PublishedSitePackageParams
    >,
): Promise<Response> {
    const { slug, revisionId } = c.req.valid("param");
    if (!slug || !revisionId) return notFound(c);
    const sitePackage =
        await sitePackageRepository(c).findSitePackageBySlug(slug);
    if (!sitePackage) return notFound(c);
    const revision = publicPackageRevision(
        sitePackage,
        await sitePackageRepository(c).findSitePackageRevisionById(
            sitePackage.id,
            revisionId,
        ),
    );
    if (!revision) return notFound(c);
    return (await serveRevisionAsset(
        c,
        revision,
        slug,
        ["site-content", slug, revisionId],
        false,
    )) satisfies PublishedSitePackageContentResponseBoundary;
}

export async function handleServePreviewSitePackage(
    c: ValidatedRequestContext<
        AppEnvironment,
        "param",
        PreviewSitePackageParams
    >,
): Promise<Response> {
    const { previewToken } = c.req.valid("param");
    if (!previewToken) return notFound(c);
    const previewTokenHash = await sha256Hex(
        new TextEncoder().encode(previewToken),
    );
    const revision =
        await sitePackageRepository(
            c,
        ).findSitePackageRevisionByPreviewTokenHash(previewTokenHash);
    if (!revision) return notFound(c);
    return (await serveRevisionAsset(
        c,
        revision,
        revision.slug,
        ["site-content", "_preview", previewToken],
        true,
    )) satisfies PreviewSitePackageContentResponseBoundary;
}
